using System;using System.IO;using System.Collections.Generic;using Microsoft.CSharp;class EmptyWriteProbe{[STAThread]static int Main(string[] args){dynamic app=ExcelProbe.Attach(Int32.Parse(args[0]));dynamic book=app.ActiveWorkbook;if(!((string)book.Name).StartsWith("VCP-"))throw new Exception("Owned fixture required");dynamic sheet=book.Worksheets.Add();sheet.Name="VCP_Empty_"+Guid.NewGuid().ToString("N").Substring(0,8);var rows=new List<string>();try{dynamic cell=sheet.Range["E2"];cell.NumberFormat="00000";cell.Value2=123.0;rows.Add("AfterNumberWrite Undo="+app.CommandBars.GetEnabledMso("Undo"));cell.ClearContents();rows.Add("AfterClearContents Undo="+app.CommandBars.GetEnabledMso("Undo")+" Empty="+((object)cell.Value2==null)+" Format="+cell.NumberFormat);cell.Value2=123.0;rows.Add("AfterNumberRewrite Undo="+app.CommandBars.GetEnabledMso("Undo"));cell.Value2=null;rows.Add("AfterNullValue2 Undo="+app.CommandBars.GetEnabledMso("Undo")+" Empty="+((object)cell.Value2==null)+" Format="+cell.NumberFormat);cell.Formula2="=1+1";cell.Value2=null;rows.Add("AfterFormulaNullValue2 HasFormula="+cell.HasFormula+" Empty="+((object)cell.Value2==null)+" Format="+cell.NumberFormat+" Undo="+app.CommandBars.GetEnabledMso("Undo"));}finally{object alerts=app.DisplayAlerts;try{app.DisplayAlerts=false;sheet.Delete();}finally{app.DisplayAlerts=alerts;}}File.WriteAllLines(args[1],rows);foreach(string r in rows)Console.WriteLine(r);return 0;} }
